import json
import sys
import unittest
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
sys.path.insert(0,str(ROOT/'backend'))
from media_links import associate_sanmar_images, sanmar_colour_alias
BASE='https://media.sanmarcanada.com/catalog/product/a/t/'
class AliasTests(unittest.TestCase):
 def test_known_aliases(self):
  for label,filename in [('Charcoal Hthr','charcoalheather'),('Hthr Cardinal','heathercardinal'),('Hthr Forest','heatherforest'),('Hthr Navy','heathernavy'),('Hthr Teal','heatherteal'),('Extreme Yello','extremeyellow'),('~Orange','orange'),('~Silver','silver')]:
   with self.subTest(label=label):
    rows=[{'variant_sku':'small','color':label,'inventory':0},{'variant_sku':'large','color':label,'inventory':30}]
    image={'url':BASE+'atc8001l_form_front_'+filename+'.jpg'}
    linked=associate_sanmar_images([image],rows,'ATC8001L')[0]
    self.assertEqual(set(linked.get('source_part_ids',[])),{'small','large'})
 def test_marked_and_plain_colours_share_image(self):
  for plain in ['Orange','Silver']:
   rows=[{'variant_sku':'one','color':plain},{'variant_sku':'two','color':'~'+plain}]
   linked=associate_sanmar_images([{'url':BASE+'atc8001l_'+plain.lower()+'.jpg'}],rows,'ATC8001L')[0]
   self.assertEqual(set(linked.get('source_part_ids',[])),{'one','two'})
 def test_other_heathers_do_not_match(self):
  rows=[{'variant_sku':'navy','color':'Hthr Navy'}]
  self.assertNotIn('source_part_ids',associate_sanmar_images([{'url':BASE+'atc8001l_heatherforest.jpg'}],rows,'ATC8001L')[0])
 def test_plain_navy_does_not_match_heather_navy(self):
  rows=[{'variant_sku':'navy','color':'Navy'}]
  self.assertNotIn('source_part_ids',associate_sanmar_images([{'url':BASE+'atc8001l_heathernavy.jpg'}],rows,'ATC8001L')[0])
 def test_wrong_style_rejected(self):
  self.assertNotIn('source_part_ids',associate_sanmar_images([{'url':BASE+'atc8000l_heatherforest.jpg'}],[{'variant_sku':'a','color':'Hthr Forest'}],'ATC8001L')[0])
 def test_wrong_host_rejected(self):
  self.assertNotIn('source_part_ids',associate_sanmar_images([{'url':'https://example.com/catalog/product/atc8001l_heatherforest.jpg'}],[{'variant_sku':'a','color':'Hthr Forest'}],'ATC8001L')[0])
 def test_authoritative_part_links_unchanged(self):
  image={'url':BASE+'atc8001l_heatherforest.jpg','source_part_ids':['explicit']}
  self.assertEqual(associate_sanmar_images([image],[{'variant_sku':'a','color':'Hthr Forest'}],'ATC8001L')[0]['source_part_ids'],['explicit'])
 def test_leading_tilde_removed(self):
  self.assertEqual(sanmar_colour_alias('~Navy'), 'navy')
  self.assertEqual(sanmar_colour_alias(' ~~Navy'), 'navy')
  self.assertEqual(sanmar_colour_alias('Navy~White'), 'navy~white')
 def test_ambiguous_colour_combination_rejected(self):
  rows=[{'variant_sku':'a','color':'Hthr Forest'},{'variant_sku':'b','color':'Hthr Navy'}]
  self.assertNotIn('source_part_ids',associate_sanmar_images([{'url':BASE+'atc8001l_heatherforest_heathernavy.jpg'}],rows,'ATC8001L')[0])

