class DiagnosticTests(unittest.TestCase):
 def test_all_230_variants_in_uploaded_diagnostic(self):
  linked=associate_sanmar_images(FIXTURE_IMAGES,FIXTURE_ROWS,'ATC8001L')
  missing=[v['variant_sku'] for v in FIXTURE_ROWS if not any(v['variant_sku'] in i.get('source_part_ids',[]) for i in linked)]
  self.assertEqual(missing,[])
  self.assertEqual(len(FIXTURE_ROWS),230)

